test('set max width', t => {
	const constrainedOutput = renderToString(
		<Box>
			<Box maxWidth={3}>
				<Text>AAAAA</Text>
			</Box>
			<Text>B</Text>
		</Box>,
		{columns: 10},
	);

	t.is(constrainedOutput, 'AAAB\nAA');

	const unconstrainedOutput = renderToString(
		<Box>
			<Box maxWidth={10}>
				<Text>AAA</Text>
			</Box>
			<Text>B</Text>
		</Box>,
	);

	t.is(unconstrainedOutput, 'AAAB');
});
